import{d as h,C as o,o as g,c as d,j as n,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"中庸·第4章","description":"《中庸》第 4 章——「道之不行也，我知之矣：知者过之，愚者不及也。」点出道之所以不行不明，皆因过与不及。","frontmatter":{"title":"中庸·第4章","description":"《中庸》第 4 章——「道之不行也，我知之矣：知者过之，愚者不及也。」点出道之所以不行不明，皆因过与不及。","category":"guide","aliases":["第4章","中庸第4章","道之不行"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-04.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-04.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-04.md"},c=h({...u,setup(p){const r=[{id:"buxing",label:"道之不行 · 道之不明",showLabel:!0,sentences:[["子曰：“道之不行也，我知之矣：",{text:"知者",glossary:"zhizhe"},{text:"过之",glossary:"guozhi"},"，",{text:"愚者",glossary:"yuzhe"},{text:"不及",glossary:"buji"},"也；道之不明也，我知之矣：",{text:"贤者",glossary:"xianzhe"},"过之，",{text:"不肖者",glossary:"buxiaozhe"},"不及也。"]],note:"孔子自谓知道「道之不行」与「道之不明」的缘由：知者（聪明人）做过了头，愚者做不到；贤者做过了头，不肖者做不到。「过」与「不及」正是道所以不明、不行的两病——中庸之难，难在此处。"},{id:"zhiwei",label:"人莫不饮食 · 鲜能知味",showLabel:!0,sentences:[["人莫不饮食也，鲜能",{text:"知味",glossary:"zhiwei"},"也。”"]],note:"「人莫不饮食也，鲜能知味也」——人人每天都在吃喝，却少有人真尝出滋味。以此喻道：人人日用不离，却少有人真知其味。全章以此喻作收。"}],s=[{id:"buxing",term:"不行",pinyin:"bù xíng",meaning:"不能实行、行不通。与此处「不明」相对：一是实践的不通，一是认识的不明。"},{id:"buming",term:"不明",pinyin:"bù míng",meaning:"不显明、不能被人明白。朱注：「道者，天理之当然，中而已矣」——道本是中，人所共由，却常不被看清。"},{id:"zhizhe",term:"知者",pinyin:"zhì zhě",meaning:"智者。「知」此处通「智」，读 zhì。"},{id:"guozhi",term:"过之",pinyin:"guò zhī",meaning:"超过了。过：过了头，与「不及」相对。"},{id:"yuzhe",term:"愚者",pinyin:"yú zhě",meaning:"愚钝的人。"},{id:"buji",term:"不及",pinyin:"bù jí",meaning:"达不到、够不上。过与不及，是偏离中道的两种方向。"},{id:"xianzhe",term:"贤者",pinyin:"xián zhě",meaning:"贤能的人。此处重在「行之过」——做得过了头。"},{id:"buxiaozhe",term:"不肖者",pinyin:"bù xiào zhě",meaning:"不贤的人。肖：似；不肖即不似（其父之贤），引申为不贤。朱注谓其「不及行，又不求所以知」。"},{id:"zhiwei",term:"知味",pinyin:"zhī wèi",meaning:"尝出味道。喻真知道、真体会。朱注：人莫不饮食，而鲜能知味——以喻道在日用而人自知者少。"}];return(z,i)=>{const l=o("DaoTextReading"),t=o("DaoKeywordCards");return g(),d("div",null,[i[0]||(i[0]=n("h1",{id:"中庸·第4章",tabindex:"-1"},[e("中庸·第4章 "),n("a",{class:"header-anchor",href:"#中庸·第4章","aria-label":'Permalink to "中庸·第4章"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=n("p",null,[e("本章点出「道之不行」「道之不明」的两种原因："),n("strong",null,"过与不及"),e("。末句用极朴素的比喻收束——人人都在吃喝，却少有人知其味。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"道之不行 · 道之不明 · 鲜能知味",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第4章 原文"}),i[3]||(i[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"知者",pinyin:["zhì","zhě"],meaning:"智者。「知」此处通「智」，读 zhì。"},{term:"过之",pinyin:["guò","zhī"],meaning:"超过了。过：过了头，与「不及」相对。"},{term:"愚者",pinyin:["yú","zhě"],meaning:"愚钝的人。"},{term:"不及",pinyin:["bù","jí"],meaning:"达不到、够不上。过与不及，是偏离中道的两种方向。"},{term:"贤者",pinyin:["xián","zhě"],meaning:"贤能的人。此处重在「行之过」——做得过了头。"},{term:"不肖者",pinyin:["bù","xiào","zhě"],meaning:"不贤的人。肖：似；不肖即不似其父之贤，引申为不贤。"},{term:"知味",pinyin:["zhī","wèi"],meaning:"尝出味道。喻真知道、真体会。"}]}),a(t,{items:[{term:"不行",pinyin:["bù","xíng"],meaning:"实践上不通。"},{term:"不明",pinyin:["bù","míng"],meaning:"认识上不明。朱注「由不明，故不行」——先不明，才不行。"}]}),i[4]||(i[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>道之不行 · 道之不明</strong>：孔子说：「道不能实行，我知道了：聪明的人做过了头，愚钝的人又做不到；道不能显明，我知道了：贤能的人做过了头，不贤的人又做不到。」</p><p><strong>人莫不饮食 · 鲜能知味</strong>：人没有不喝水吃饭的，却很少有人能尝出味道。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第四章回答的是「道为什么行不通、也说不明」。孔子的答案很简单：<strong>过与不及</strong>——聪明的人和贤人「过」，愚钝的人和不贤的人「不及」，两头都离开了中。</p><p>最后一句是全章的题眼：「人莫不饮食也，鲜能知味也。」道并不远，人人日日都在其中，可<strong>知其味</strong>的人极少。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把「过」与「不及」并列为偏离</strong>：通常人以为「做得更多」总比「做得不够」好，这里两者同属偏差。</li><li><strong>它分出「不行」与「不明」两层</strong>：一是行的不通，一是认识的不明。朱注说「由不明，故不行」——<strong>先看不清，才做不到</strong>，顺序不能颠倒。</li><li><strong>它用饮食作喻，回到首章</strong>：「不可须臾离」是从「道离不开人」说；「莫不饮食」是从「人离不开道」说。两边都在讲：道在日用之中，难的从来不是「找不到」，而是「尝不出」。</li><li><strong>它给了中庸一个可日常验证的标准</strong>：不必去问高深的道理，先问自己——这每天都在做的事，我尝出味了吗？</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>诊断自己</strong>：我容易「过」还是容易「不及」？同一件事上，会不会两种都犯过？</li><li><strong>先明后行</strong>：事情推不动时，先回头看是不是「没看清」——不明，则不行。</li><li><strong>别把道推远</strong>：道就在饮食日用里，不必等某个更高的场合才开始。</li><li><strong>练「知味」</strong>：做熟的事最容易「自动完成」；能重新尝出味，是不小的功夫。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说，道为什么行不通、说不明，他很清楚：聪明人和贤人容易<strong>过</strong>，愚钝的人和不贤的人容易<strong>不及</strong>——两边都偏出了中。</p><p>然后是那句诗一样的话：<strong>人没有不吃饭喝水的，可很少人尝得出味道。</strong></p><p>这句话把整章说透了：道不在别处，就在每个人每天都在做的事里。问题不是「找不到」，而是「活在里头却不知道」。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「过」与「不及」——我更容易犯哪一种？有没有一件具体的事可以作证？</li><li>「由不明，故不行」——我有没有「明明知道该做却做不成」的事？回头看，是行的问题，还是明的问题？</li><li>「人莫不饮食，鲜能知味」——我每天都在做、却已经尝不出味的事，是哪一件？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-03">中庸·第3章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-05">中庸·第5章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',22))])}}});export{y as __pageData,c as default};
